#include <stdio.h>

int main(void) {
  remove("slate_stdio_fread_size_one.tmp");
  FILE *f = fopen("slate_stdio_fread_size_one.tmp", "w");
  if (!f) {
    puts("open-fail");
    return 0;
  }
  fputs("hello world", f);
  fclose(f);

  FILE *g = fopen("slate_stdio_fread_size_one.tmp", "r");
  if (!g) {
    puts("reopen-fail");
    return 0;
  }
  char   buf[16] = {0};
  size_t n       = fread(buf, 1, 11, g);
  printf("%zu %s\n", n, buf);
  fclose(g);
  remove("slate_stdio_fread_size_one.tmp");
  return 0;
}




